describe("redirect method rewriting (RFC 9110 section 15.4)", () => {
  const originalFetch = global.fetch;

  /* The method the second hop is sent with, after a first hop answered with the given status. */
  const followedMethod = async (
    status: number,
    method: string,
  ): Promise<unknown> => {
    const seen: unknown[] = [];
    global.fetch = (async (
      _input: string | URL | Request,
      init?: RequestInit,
    ): Promise<Response> => {
      seen.push(init?.method);
      if (seen.length === 1) {
        return new Response(null, {
          status,
          headers: { Location: "https://secure.example/next" },
        });
      }
      return new Response("{}", {
        status: 200,
        headers: { "Content-Type": "application/json" },
      });
    }) as typeof fetch;
    const client = new DefaultApiClient(
      TransportOptions.builder().followRedirects(true).build(),
    );
    await client.sendRequest(
      method,
      "https://secure.example/start",
      {},
      '{"x":1}',
    );
    return seen[1];
  };

  afterEach(() => {
    global.fetch = originalFetch;
  });

  test("bhv langnode 079 every redirect status follows with the stated method and keeps or drops the body", async () => {
    for (const [status, method, expectedMethod, bodyKept] of [
      [301, "POST", "GET", false],
      [302, "POST", "GET", false],
      [301, "PUT", "PUT", true],
      [302, "PATCH", "PATCH", true],
      [302, "DELETE", "DELETE", true],
      [303, "POST", "GET", false],
      [303, "PUT", "GET", false],
      [303, "DELETE", "GET", false],
      [303, "HEAD", "HEAD", false],
      [307, "PUT", "PUT", true],
      [308, "DELETE", "DELETE", true],
    ] as const) {
      const calls: Array<{ method: unknown; body: unknown }> = [];
      global.fetch = (async (
        _input: string | URL | Request,
        init?: RequestInit,
      ): Promise<Response> => {
        calls.push({ method: init?.method, body: init?.body });
        if (calls.length === 1) {
          return new Response(null, {
            status,
            headers: { Location: "https://secure.example/next" },
          });
        }
        return new Response("{}", {
          status: 200,
          headers: { "Content-Type": "application/json" },
        });
      }) as typeof fetch;

      const client = new DefaultApiClient(
        TransportOptions.builder().followRedirects(true).build(),
      );
      const response = await client.sendRequest(
        method,
        "https://secure.example/start",
        { "Content-Type": "application/json" },
        '{"x":1}',
      );

      expect(response.statusCode).toBe(200);
      expect(calls[1].method).toBe(expectedMethod);
      if (bodyKept) {
        expect(calls[1].body).toBeDefined();
      } else {
        expect(calls[1].body ?? null).toBeNull();
      }
    }
  });

  it("bhv redirects 029 rewrites a PUT to GET only on a 303 and keeps it on a 307", async () => {
    expect(await followedMethod(307, "PUT")).toBe("PUT");
    expect(await followedMethod(303, "PUT")).toBe("GET");
  });

  it("bhv redirects 048 a 301 or 302 turns a POST into a GET, and PUT, PATCH, DELETE, HEAD and GET keep their method", async () => {
    for (const status of [301, 302]) {
      expect(await followedMethod(status, "POST")).toBe("GET");
    }
    for (const method of ["PUT", "PATCH", "DELETE", "HEAD", "GET"]) {
      expect(await followedMethod(301, method)).toBe(method);
    }
  });

  it("bhv redirects 050 the follow-up method of 301, 302, 303, 307 and 308 matches the RFC 9110 table", async () => {
    expect(await followedMethod(301, "POST")).toBe("GET");
    expect(await followedMethod(302, "POST")).toBe("GET");
    expect(await followedMethod(303, "POST")).toBe("GET");
    expect(await followedMethod(307, "POST")).toBe("POST");
    expect(await followedMethod(308, "POST")).toBe("POST");
    expect(await followedMethod(307, "PUT")).toBe("PUT");
    expect(await followedMethod(308, "PUT")).toBe("PUT");
    expect(await followedMethod(303, "HEAD")).toBe("HEAD");
  });

  it("bhv redirects 051 a 303 turns a follow-up request into a GET, except that a HEAD request stays HEAD", async () => {
    expect(await followedMethod(303, "DELETE")).toBe("GET");
    expect(await followedMethod(303, "HEAD")).toBe("HEAD");
  });

  it("bhv redirects 053 Authorization is removed when the scheme changes between https and http on the same host, either way", async () => {
    const pairs: Array<[string, string]> = [
      ["https://secure.example/start", "http://secure.example/next"],
      ["http://secure.example/start", "https://secure.example/next"],
    ];
    for (const [start, next] of pairs) {
      const seen: Array<Record<string, string>> = [];
      global.fetch = (async (
        _input: string | URL | Request,
        init?: RequestInit,
      ): Promise<Response> => {
        seen.push({ ...(init?.headers as Record<string, string>) });
        if (seen.length === 1) {
          return new Response(null, {
            status: 302,
            headers: { Location: next },
          });
        }
        return new Response("{}", {
          status: 200,
          headers: { "Content-Type": "application/json" },
        });
      }) as typeof fetch;
      const client = new DefaultApiClient(
        TransportOptions.builder().followRedirects(true).build(),
      );

      await client.sendRequest(
        "GET",
        start,
        { Authorization: "Bearer secret" },
        null,
      );

      expect(seen[0]!["Authorization"]).toBe("Bearer secret");
      expect(seen[1]!["Authorization"]).toBeUndefined();
    }
  });

  it("bhv redirects 036 a 303 turns every method except HEAD into GET", async () => {
    for (const method of ["POST", "PUT", "PATCH", "DELETE"]) {
      expect(await followedMethod(303, method)).toBe("GET");
    }
    expect(await followedMethod(303, "HEAD")).toBe("HEAD");
  });

  it("bhv retries 017 refuses to replay a PUT body across an https to http 302 downgrade", async () => {
    global.fetch = (async (): Promise<Response> =>
      new Response(null, {
        status: 302,
        headers: { Location: "http://other.example/x" },
      })) as typeof fetch;
    const client = new DefaultApiClient(
      TransportOptions.builder().followRedirects(true).build(),
    );
    await expect(
      client.sendRequest("PUT", "https://secure.example/start", {}, '{"x":1}'),
    ).rejects.toThrow(
      /Refusing to replay request body across HTTPS->HTTP redirect/,
    );
  });
});

describe("text/plain bodies are never decoded", () => {
  it("bhv operations 161 a text/plain response is returned as the raw text even when it looks like base64", () => {
    expect(
      DefaultApiClient.decodeBody(Buffer.from("aGVsbG8="), "text/plain"),
    ).toBe("aGVsbG8=");
  });
});

/*
 * T-D3: a Location pointing at a non-HTTP(S) scheme must be refused with a
 * loud, typed ApiError, never silently surfaced as the 3xx response.
 */
describe("redirect to non-HTTP(S) scheme is refused", () => {
  const originalFetch = global.fetch;
  afterEach(() => {
    global.fetch = originalFetch;
  });

  it("bhv redirects 055 a Location with an ftp scheme is refused with an error", async () => {
    global.fetch = (async (): Promise<Response> =>
      new Response(null, {
        status: 302,
        headers: { Location: "ftp://files.example/x" },
      })) as typeof fetch;
    const client = new DefaultApiClient(
      TransportOptions.builder().followRedirects(true).build(),
    );
    await expect(
      client.sendRequest("GET", "https://api.example/start", {}, null),
    ).rejects.toThrow(ApiError);
  });

  it("bhv redirects 020 throws an ApiError when Location uses a file:/javascript: scheme", async () => {
    global.fetch = (async (): Promise<Response> => {
      return new Response(null, {
        status: 302,
        headers: { Location: "file:///etc/passwd" },
      });
    }) as typeof fetch;

    const transport = TransportOptions.builder().followRedirects(true).build();
    const client = new DefaultApiClient(transport);
    const error = await client
      .sendRequest("GET", "http://api.example/start", {}, null)
      .catch((e: unknown) => e);
    // A refused redirect is a response that could not be used: an ApiError
    // with the 3xx status, never a NetworkError.
    expect((error as Error).constructor).toBe(ApiError);
    expect((error as ApiError).statusCode).toBe(302);
    // D13: a refusal keeps the real response headers, never null.
    expect((error as ApiError).responseHeaders).not.toBeNull();
  });
});

/*
 * An intermediate 3xx body is never read, so the client must cancel it or
 * undici keeps the connection busy until the body is garbage collected.
 */
describe("redirect responses release their body", () => {
  const originalFetch = global.fetch;
  afterEach(() => {
    global.fetch = originalFetch;
  });

  function redirectWithTrackedBody(
    location: string,
    label: string,
    cancelled: string[],
  ): Response {
    const body = new ReadableStream<Uint8Array>({
      start(controller) {
        controller.enqueue(new TextEncoder().encode("moved"));
      },
      cancel() {
        cancelled.push(label);
      },
    });
    return new Response(body, { status: 302, headers: { Location: location } });
  }

  it("bhv redirects 017 cancels the body of each redirect it follows", async () => {
    const cancelled: string[] = [];
    let call = 0;
    global.fetch = (async (): Promise<Response> => {
      call++;
      if (call === 1)
        return redirectWithTrackedBody(
          "http://api.example/b",
          "first",
          cancelled,
        );
      if (call === 2)
        return redirectWithTrackedBody(
          "http://api.example/c",
          "second",
          cancelled,
        );
      return new Response("done", { status: 200 });
    }) as typeof fetch;

    const client = new DefaultApiClient(
      TransportOptions.builder().followRedirects(true).build(),
    );
    const response = await client.sendRequest(
      "GET",
      "http://api.example/a",
      {},
      null,
    );

    expect(response.statusCode).toBe(200);
    expect(cancelled).toEqual(["first", "second"]);
  });

  it("bhv transport 064 the intermediate response of a refused HTTPS to HTTP redirect is released", async () => {
    const cancelled: string[] = [];
    global.fetch = (async (): Promise<Response> => {
      const body = new ReadableStream<Uint8Array>({
        start(controller) {
          controller.enqueue(new TextEncoder().encode("moved"));
        },
        cancel() {
          cancelled.push("downgrade");
        },
      });
      return new Response(body, {
        status: 307,
        headers: { Location: "http://evil.example/steal" },
      });
    }) as typeof fetch;

    const client = new DefaultApiClient(
      TransportOptions.builder().followRedirects(true).build(),
    );
    await client
      .sendRequest(
        "POST",
        "https://secure.example/token",
        { "Content-Type": "text/plain" },
        "grant=refused",
      )
      .catch((e: unknown) => e);

    expect(cancelled).toEqual(["downgrade"]);
  });

  it("bhv redirects 014 cancels the body of a redirect it refuses to follow", async () => {
    const cancelled: string[] = [];
    global.fetch = (async (): Promise<Response> =>
      redirectWithTrackedBody(
        "file:///etc/passwd",
        "refused",
        cancelled,
      )) as typeof fetch;

    const client = new DefaultApiClient(
      TransportOptions.builder().followRedirects(true).build(),
    );
    await client
      .sendRequest("GET", "http://api.example/a", {}, null)
      .catch((e: unknown) => e);

    expect(cancelled).toEqual(["refused"]);
  });

  it("bhv redirects 018 cancels every body, the last one included, when the redirect budget is exhausted", async () => {
    const cancelled: string[] = [];
    let call = 0;
    global.fetch = (async (): Promise<Response> => {
      call++;
      return redirectWithTrackedBody(
        `http://api.example/hop${call}`,
        `hop${call}`,
        cancelled,
      );
    }) as typeof fetch;

    const client = new DefaultApiClient(
      TransportOptions.builder().followRedirects(true).maxRedirects(2).build(),
    );
    await client
      .sendRequest("GET", "http://api.example/a", {}, null)
      .catch((e: unknown) => e);

    expect(cancelled).toEqual(["hop1", "hop2", "hop3"]);
  });
});

/*
 * T-D1: exhausting the redirect budget must throw "too many redirects",
 * not silently return the last 3xx response as if it were normal.
 */
describe("redirect exhaustion throws", () => {
  const originalFetch = global.fetch;
  afterEach(() => {
    global.fetch = originalFetch;
  });

  it("bhv redirects 046 a chain within the limit is followed to its target and one past it raises too-many-redirects", async () => {
    let n = 0;
    global.fetch = (async (): Promise<Response> => {
      n++;
      if (n <= 2) {
        return new Response(null, {
          status: 302,
          headers: { Location: `http://api.example/hop${n}` },
        });
      }
      return new Response('{"ok":true}', {
        status: 200,
        headers: { "Content-Type": "application/json" },
      });
    }) as typeof fetch;
    const within = await new DefaultApiClient(
      TransportOptions.builder().followRedirects(true).maxRedirects(3).build(),
    ).sendRequest("GET", "http://api.example/start", {}, null);
    expect(within.statusCode).toBe(200);
    expect(n).toBe(3);

    n = 0;
    const error = await new DefaultApiClient(
      TransportOptions.builder().followRedirects(true).maxRedirects(1).build(),
    )
      .sendRequest("GET", "http://api.example/start", {}, null)
      .catch((caught: unknown) => caught);
    expect((error as ApiError).statusCode).toBe(302);
    expect((error as ApiError).message).toContain(
      "Too many redirects (exceeded 1)",
    );
  });

  it("bhv redirects 047 a refused redirect and a followed redirect in parallel requests do not change each other", async () => {
    global.fetch = (async (
      input: string | URL | Request,
    ): Promise<Response> => {
      const url = String(input);
      if (url.includes("loop")) {
        return new Response(null, { status: 302, headers: { Location: url } });
      }
      if (url.includes("moved")) {
        return new Response(null, {
          status: 302,
          headers: { Location: "http://api.example/final" },
        });
      }
      return new Response('{"ok":true}', {
        status: 200,
        headers: { "Content-Type": "application/json" },
      });
    }) as typeof fetch;
    const client = new DefaultApiClient(
      TransportOptions.builder().followRedirects(true).maxRedirects(3).build(),
    );

    const [looping, moved] = await Promise.allSettled([
      client.sendRequest("GET", "http://api.example/loop", {}, null),
      client.sendRequest("GET", "http://api.example/moved", {}, null),
    ]);

    expect(looping.status).toBe("rejected");
    expect(moved).toMatchObject({
      status: "fulfilled",
      value: { statusCode: 200 },
    });
  });

  it("bhv redirects 054 a redirect chain that runs past the timeout budget fails, and the budget is shared across hops", async () => {
    const chain = (redirects: number): typeof fetch => {
      let n = 0;
      return (async (
        _input: string | URL | Request,
        init?: RequestInit,
      ): Promise<Response> =>
        new Promise((resolve, reject) => {
          const timer = setTimeout(() => {
            n++;
            resolve(
              n <= redirects
                ? new Response(null, {
                    status: 302,
                    headers: { Location: `http://api.example/hop${n}` },
                  })
                : new Response('{"ok":true}', {
                    status: 200,
                    headers: { "Content-Type": "application/json" },
                  }),
            );
          }, 300);
          init?.signal?.addEventListener("abort", () => {
            clearTimeout(timer);
            reject(init.signal!.reason);
          });
        })) as typeof fetch;
    };
    const build = () =>
      new DefaultApiClient(
        TransportOptions.builder()
          .followRedirects(true)
          .maxRedirects(10)
          .timeout(1000)
          .build(),
      );

    global.fetch = chain(2);
    const within = await build().sendRequest(
      "GET",
      "http://api.example/start",
      {},
      null,
    );
    expect(within.statusCode).toBe(200);

    global.fetch = chain(4);
    const error = await build()
      .sendRequest("GET", "http://api.example/start", {}, null)
      .catch((caught: unknown) => caught);
    expect((error as Error).constructor).toBe(NetworkTimeoutError);
  });

  it("bhv redirects 026 throws an ApiError once maxRedirects is exceeded", async () => {
    let n = 0;
    global.fetch = (async (): Promise<Response> => {
      n++;
      // Always redirect onward so the budget is exhausted.
      return new Response(null, {
        status: 302,
        headers: { Location: `http://api.example/hop${n}` },
      });
    }) as typeof fetch;

    const transport = TransportOptions.builder()
      .followRedirects(true)
      .maxRedirects(3)
      .build();
    const client = new DefaultApiClient(transport);
    const error = await client
      .sendRequest("GET", "http://api.example/start", {}, null)
      .catch((e: unknown) => e);
    expect((error as Error).constructor).toBe(ApiError);
    expect((error as ApiError).statusCode).toBe(302);
    expect((error as ApiError).message).toContain(
      "Too many redirects (exceeded 3)",
    );
    expect((error as ApiError).responseHeaders).toHaveProperty("location");
  });

  it("bhv redirects 023 returns the last 3xx when the budget is used up and it has no Location", async () => {
    let n = 0;
    global.fetch = (async (): Promise<Response> => {
      n++;
      if (n === 1) {
        return new Response(null, {
          status: 302,
          headers: { Location: "http://api.example/b" },
        });
      }
      return new Response("terminal", { status: 302 });
    }) as typeof fetch;

    const transport = TransportOptions.builder()
      .followRedirects(true)
      .maxRedirects(1)
      .build();
    const client = new DefaultApiClient(transport);
    const response = await client.sendRequest(
      "GET",
      "http://api.example/a",
      {},
      null,
    );
    expect(response.statusCode).toBe(302);
  });
});

/*
 * T-D4: use-after-close is a wrong call order, so it throws the
 * invalid-state built-in Error rather than a foreign undici exception or
 * silently succeeding.
 */
describe("use-after-close", () => {
  it("bhv lifecycle 023 throws the invalid-state Error when sendRequest is called after close()", async () => {
    const client = new DefaultApiClient();
    await client.close();
    const error = await client
      .sendRequest("GET", "http://api.example/x", {}, null)
      .catch((e: unknown) => e);
    expect((error as Error).constructor).toBe(Error);
    expect(error).not.toBeInstanceOf(ApiError);
    expect((error as Error).message).toBe(
      "ApiClient has been closed and can no longer send requests",
    );
  });
});

/*
 * F1078: close() is graceful and idempotent. A request already running
 * finishes, a request issued afterwards fails with the one closed-client
 * error, and the transport the SDK created is released when the last running
 * request completes. A transport the caller supplied is never touched.
 */
describe("graceful close", () => {
  const closedMessage =
    "ApiClient has been closed and can no longer send requests";

  function slowServer(): Promise<{
    url: string;
    arrived: Promise<void>;
    answer: () => void;
    stop: () => Promise<void>;
  }> {
    return new Promise((resolve) => {
      let arrived!: () => void;
      const arrivedPromise = new Promise<void>((done) => {
        arrived = done;
      });
      let pending: http.ServerResponse | undefined;
      const slow = http.createServer((_req, res) => {
        pending = res;
        arrived();
      });
      slow.listen(0, "127.0.0.1", () => {
        resolve({
          url: `http://127.0.0.1:${(slow.address() as { port: number }).port}/slow`,
          arrived: arrivedPromise,
          answer: () => {
            pending?.writeHead(200, { "Content-Type": "text/plain" });
            pending?.end("late");
          },
          stop: async () => {
            slow.closeAllConnections();
            await new Promise<void>((done) => slow.close(() => done()));
          },
        });
      });
    });
  }

  it("bhv lifecycle 043 a request after close fails with the closed-client error and never reaches the network", async () => {
    let fetched = 0;
    const originalFetch = global.fetch;
    global.fetch = (async (): Promise<Response> => {
      fetched++;
      return new Response("{}");
    }) as typeof fetch;
    try {
      const client = new DefaultApiClient(TransportOptions.builder().build());
      await client.close();
      await expect(
        client.sendRequest("GET", "https://example.invalid/x", {}, null),
      ).rejects.toThrow(
        "ApiClient has been closed and can no longer send requests",
      );
      expect(fetched).toBe(0);
    } finally {
      global.fetch = originalFetch;
    }
  });

  it("bhv lifecycle 044 a request in flight when the client closes still completes after its retry", async () => {
    let calls = 0;
    const originalFetch = global.fetch;
    global.fetch = (async (): Promise<Response> => {
      calls++;
      if (calls === 1) {
        return new Response(null, { status: 503 });
      }
      return new Response('{"ok":true}', {
        status: 200,
        headers: { "Content-Type": "application/json" },
      });
    }) as typeof fetch;
    try {
      const client = new DefaultApiClient(
        TransportOptions.builder().maxRetries(1).build(),
      );
      const running = client.sendRequest(
        "GET",
        "https://example.invalid/x",
        {},
        null,
      );
      await client.close();
      const response = await running;
      expect(response.statusCode).toBe(200);
      expect(calls).toBe(2);
    } finally {
      global.fetch = originalFetch;
    }
  });

  it("bhv lifecycle 021 lets a request that is already running finish", async () => {
    const slow = await slowServer();
    const client = new DefaultApiClient(
      TransportOptions.builder().maxRetries(0).build(),
    );
    try {
      const pending = client.sendRequest("GET", slow.url, {}, null);
      await slow.arrived;
      await client.close();
      slow.answer();

      const response = await pending;

      expect(response.statusCode).toBe(200);
      expect(response.body).toBe("late");
    } finally {
      await slow.stop();
    }
  });

  it("bhv lifecycle 037 releases the transport the SDK created only when the last running request completes", async () => {
    const slow = await slowServer();
    const client = new DefaultApiClient(
      TransportOptions.builder().maxRetries(0).maxRedirects(2).build(),
    );
    const dispatcher = (
      client as unknown as { dispatcher: { closed: boolean } }
    ).dispatcher;
    try {
      const pending = client.sendRequest("GET", slow.url, {}, null);
      await slow.arrived;
      await client.close();

      expect(dispatcher.closed).toBe(false);

      slow.answer();
      await pending;

      expect(dispatcher.closed).toBe(true);
    } finally {
      await slow.stop();
    }
  });

  it("bhv lifecycle 022 releases the transport at once when no request is running, and a second close() is a no-op", async () => {
    const client = new DefaultApiClient(
      TransportOptions.builder().maxRedirects(2).build(),
    );
    const dispatcher = (
      client as unknown as { dispatcher: { closed: boolean } }
    ).dispatcher;

    await client.close();

    expect(dispatcher.closed).toBe(true);
    await expect(client.close()).resolves.toBeUndefined();
  });

  it("bhv lifecycle 019 a request issued while the last one is finishing fails with the closed-client error", async () => {
    const slow = await slowServer();
    const client = new DefaultApiClient(
      TransportOptions.builder().maxRetries(0).build(),
    );
    try {
      const pending = client.sendRequest("GET", slow.url, {}, null);
      await slow.arrived;
      await client.close();

      await expect(
        client.sendRequest("GET", slow.url, {}, null),
      ).rejects.toThrow(new Error(closedMessage));

      slow.answer();
      await pending;
    } finally {
      await slow.stop();
    }
  });

  it("bhv langnode 074 cancels a running request through its own signal, never through close()", async () => {
    const slow = await slowServer();
    const client = new DefaultApiClient(
      TransportOptions.builder().maxRetries(0).build(),
    );
    const controller = new AbortController();
    try {
      const pending = client
        .sendRequest("GET", slow.url, {}, null, { signal: controller.signal })
        .catch((e: unknown) => e);
      await slow.arrived;
      await client.close();
      controller.abort();

      const error = await pending;

      expect((error as Error).name).toBe("AbortError");
    } finally {
      await slow.stop();
    }
  });

  it("bhv lifecycle 020 never closes a fetch the caller supplied, however many times it closes", async () => {
    let called = 0;
    const customFetch = (async (): Promise<Response> => {
      called++;
      return new Response("{}");
    }) as typeof fetch;
    const client = new DefaultApiClient(
      TransportOptions.builder().fetch(customFetch).build(),
    );

    await client.sendRequest("GET", "http://example.invalid/", {}, null);
    await client.close();
    await client.close();

    expect(called).toBe(1);
    expect(await customFetch("http://example.invalid/")).toBeInstanceOf(
      Response,
    );
  });
});

describe("request header and byte body handling", () => {
  const originalFetch = global.fetch;
  afterEach(() => {
    global.fetch = originalFetch;
  });

  it("bhv transport 047 lets a caller header replace a default of another case", async () => {
    let seen: Record<string, string> = {};
    global.fetch = (async (
      _url: unknown,
      init: { headers: Record<string, string> },
    ) => {
      seen = init.headers;
      return new Response("{}", { status: 200 });
    }) as unknown as typeof fetch;
    const transport = TransportOptions.builder()
      .defaultHeaders({ accept: "application/vnd.x+json" })
      .build();
    const client = new DefaultApiClient(transport);
    await client.sendRequest(
      "GET",
      "http://api.example/x",
      { Accept: "application/json" },
      null,
    );
    const accepts = Object.keys(seen).filter(
      (key) => key.toLowerCase() === "accept",
    );
    expect(accepts).toEqual(["Accept"]);
  });

  it("bhv redirects 016 leaves the default headers off a request that asks for noDefaultHeaders", async () => {
    let seen: Record<string, string> = {};
    global.fetch = (async (
      _url: unknown,
      init: { headers: Record<string, string> },
    ) => {
      seen = init.headers;
      return new Response("{}", { status: 200 });
    }) as unknown as typeof fetch;
    const transport = TransportOptions.builder()
      .defaultHeaders({ Authorization: "Bearer api-only" })
      .build();
    const client = new DefaultApiClient(transport);
    await client.sendRequest("POST", "http://idp.example/token", {}, "a=b", {
      noDefaultHeaders: true,
    });
    expect(Object.keys(seen).map((key) => key.toLowerCase())).not.toContain(
      "authorization",
    );
  });

  it("bhv redirects 056 a request that opts out of default headers sends none, and the next normal request sends them again", async () => {
    const seen: Array<Record<string, string>> = [];
    global.fetch = (async (
      _url: unknown,
      init: { headers: Record<string, string> },
    ) => {
      seen.push(init.headers);
      return new Response("{}", { status: 200 });
    }) as unknown as typeof fetch;
    const client = new DefaultApiClient(
      TransportOptions.builder()
        .defaultHeaders({ Authorization: "Bearer api-only" })
        .build(),
    );

    await client.sendRequest("POST", "http://idp.example/token", {}, "a=b", {
      noDefaultHeaders: true,
    });
    await client.sendRequest("GET", "http://api.example/items", {}, null);

    expect(Object.keys(seen[0]!).map((key) => key.toLowerCase())).not.toContain(
      "authorization",
    );
    expect(seen[1]!["Authorization"]).toBe("Bearer api-only");
  });

  it("bhv misc 202 a text body sent without a declared content type goes out as bare JSON", async () => {
    let seenHeaders: Record<string, string> = {};
    global.fetch = (async (
      _url: unknown,
      init: { headers: Record<string, string> },
    ) => {
      seenHeaders = init.headers;
      return new Response("{}", { status: 200 });
    }) as unknown as typeof fetch;
    const client = new DefaultApiClient();

    await client.sendRequest("POST", "http://api.example/x", {}, "hello");

    expect(seenHeaders["Content-Type"]).toBe("application/json");
  });
  it("bhv misc 217 sends a plain Uint8Array body as raw bytes, not multipart", async () => {
    let seenBody: unknown;
    let seenHeaders: Record<string, string> = {};
    global.fetch = (async (
      _url: unknown,
      init: { body: unknown; headers: Record<string, string> },
    ) => {
      seenBody = init.body;
      seenHeaders = init.headers;
      return new Response("{}", { status: 200 });
    }) as unknown as typeof fetch;
    const client = new DefaultApiClient();
    await client.sendRequest(
      "PUT",
      "http://api.example/x",
      { "Content-Type": "image/png" },
      new Uint8Array([1, 2, 3]) as unknown as Buffer,
    );
    expect(Buffer.from(seenBody as Uint8Array)).toEqual(Buffer.from([1, 2, 3]));
    expect(seenHeaders["Content-Type"]).toBe("image/png");
  });
});

/*
 * response-body-read-error-not-wrapped: a failure during the post-headers
 * body read (connection reset / truncated body) must be wrapped in the
 * uniform ApiError type, not leak the raw fetch error.
 */
describe("body-read error is wrapped in NetworkError", () => {
  const originalFetch = global.fetch;
  afterEach(() => {
    global.fetch = originalFetch;
  });

  it("bhv transport 032 wraps an arrayBuffer() rejection in NetworkError with the cause kept", async () => {
    global.fetch = (async (): Promise<Response> => {
      // A Response whose body read rejects, simulating a mid-stream reset.
      const resp = new Response("", { status: 200 });
      Object.defineProperty(resp, "arrayBuffer", {
        value: () => Promise.reject(new TypeError("terminated")),
      });
      return resp;
    }) as typeof fetch;

    const client = new DefaultApiClient();
    const error = await client
      .sendRequest("GET", "http://api.example/x", {}, null)
      .catch((e: unknown) => e);
    expect((error as Error).constructor).toBe(NetworkError);
    expect((error as NetworkError).statusCode).toBe(0);
    expect(((error as NetworkError).cause as Error).message).toBe("terminated");
  });

  describe("against a server that breaks the body after sending the headers", () => {
    let broken: http.Server;
    let brokenUrl: string;

    beforeAll(async () => {
      broken = http.createServer((req, res) => {
        res.writeHead(200, {
          "Content-Type": "text/plain",
          "Content-Length": "100",
        });
        res.write("partial");
        if (req.url === "/truncated") {
          setTimeout(() => res.destroy(), 20);
        }
      });
      await new Promise<void>((resolve) =>
        broken.listen(0, "127.0.0.1", resolve),
      );
      brokenUrl = `http://127.0.0.1:${(broken.address() as { port: number }).port}`;
    });

    afterAll(async () => {
      broken.closeAllConnections();
      await new Promise<void>((resolve) => broken.close(() => resolve()));
    });

    it("bhv errors 038 a body truncated after the headers throws NetworkError with status 0", async () => {
      const client = new DefaultApiClient();
      const error = await client
        .sendRequest("GET", `${brokenUrl}/truncated`, {}, null)
        .catch((e: unknown) => e);
      await client.close();
      expect((error as Error).constructor).toBe(NetworkError);
      expect((error as NetworkError).statusCode).toBe(0);
      expect((error as NetworkError).cause).toBeDefined();
    });

    it("bhv transport 029 a body that stalls after the headers throws NetworkTimeoutError with status 0", async () => {
      const client = new DefaultApiClient(
        TransportOptions.builder().timeout(300).build(),
      );
      const error = await client
        .sendRequest("GET", `${brokenUrl}/stalled`, {}, null)
        .catch((e: unknown) => e);
      await client.close();
      expect((error as Error).constructor).toBe(NetworkTimeoutError);
      expect((error as NetworkTimeoutError).statusCode).toBe(0);
    });
  });
});

/*
 * Canonical scenario AL — Content-Encoding lie. A server advertises
 * `Content-Encoding: gzip` but the body is NOT a valid gzip stream. The
 * client MUST surface the SDK's ApiError (no crash, no corrupt-byte
 * passthrough), matching java/python/ruby/go/php/rust/elixir which wrap the
 * decompression failure.
 *
 * On the real-network path undici decodes Content-Encoding transparently and
 * throws on a malformed stream (already wrapped as ApiError by the body-read
 * catch). This unit test pins the behaviour deterministically by mocking
 * `fetch` to return a body that carries the gzip magic bytes (0x1F 0x8B) --
 * so it claims AND looks like gzip -- but is not a decodable gzip stream.
 * RED before the fix (the undecoded bytes were base64'd and returned), GREEN
 * after (DefaultApiClient.ensureDecoded gunzips, fails, and throws ApiError).
 */
describe("Content-Encoding lie surfaces ApiError (canonical AL)", () => {
  const originalFetch = global.fetch;
  afterEach(() => {
    global.fetch = originalFetch;
  });

  it("bhv transport 034 throws ApiError when Content-Encoding: gzip body is not valid gzip", async () => {
    // gzip magic prefix + garbage tail: declares gzip, looks like gzip, but
    // is not a valid gzip stream.
    const lyingBody = Buffer.concat([
      Buffer.from([0x1f, 0x8b]),
      Buffer.from("this is not a valid gzip stream", "utf-8"),
    ]);
    global.fetch = (async (): Promise<Response> => {
      return new Response(lyingBody, {
        status: 200,
        headers: {
          "Content-Type": "application/json",
          "Content-Encoding": "gzip",
        },
      });
    }) as typeof fetch;

    const client = new DefaultApiClient();
    const error = await client
      .sendRequest("GET", "http://api.example/lie", {}, null)
      .catch((e: unknown) => e);
    expect((error as Error).constructor).toBe(ApiError);
    expect(error).not.toBeInstanceOf(NetworkError);
    expect((error as ApiError).statusCode).toBe(200);
  });

  it("bhv transport 088 decodes a genuinely gzip-encoded body that the fetch layer left compressed", async () => {
    // ensureDecoded is exercised directly: a valid gzip stream still on the
    // wire is decompressed rather than passed through as base64. It is async
    // because the shared base decodes via the Web-standard DecompressionStream
    // so the gzip-lie guard runs on every runtime.
    const valid = zlib.gzipSync(Buffer.from('{"userId":1}', "utf-8"));
    const out = await DefaultApiClient.ensureDecoded(valid, "gzip");
    expect(out.toString("utf-8")).toBe('{"userId":1}');
  });

  it("bhv langnode 075 leaves an already-decoded body untouched (no double-decode)", async () => {
    // When the fetch layer has already decoded the body the gzip magic is gone,
    // so ensureDecoded must pass the plaintext through unchanged.
    const decoded = Buffer.from('{"userId":1}', "utf-8");
    const out = await DefaultApiClient.ensureDecoded(decoded, "gzip");
    expect(out.toString("utf-8")).toBe('{"userId":1}');
  });

  it("bhv transport 073 throws ApiError directly from ensureDecoded on invalid gzip bytes", async () => {
    const lyingBody = Buffer.concat([
      Buffer.from([0x1f, 0x8b]),
      Buffer.from("garbage", "utf-8"),
    ]);
    await expect(
      DefaultApiClient.ensureDecoded(lyingBody, "gzip"),
    ).rejects.toThrow(ApiError);
  });

  it("bhvMisc285 a response with a content encoding the SDK cannot decode is refused with the exact unsupported-encoding message", async () => {
    await expect(
      DefaultApiClient.ensureDecoded(
        Buffer.from("payload", "utf-8"),
        "compress",
        200,
      ),
    ).rejects.toMatchObject({
      name: "ApiError",
      message: "Unsupported Content-Encoding 'compress'",
    });
  });

  it("bhv transport 035 decompresses a zlib-wrapped deflate response", async () => {
    const body = zlib.deflateSync(Buffer.from('{"userId":1}', "utf-8"));
    const srv = http.createServer((_req, res) => {
      res.writeHead(200, {
        "Content-Type": "application/json",
        "Content-Encoding": "deflate",
      });
      res.end(body);
    });
    await new Promise<void>((resolve) => srv.listen(0, "127.0.0.1", resolve));
    try {
      const port = (srv.address() as { port: number }).port;
      const client = new DefaultApiClient();
      const response = await client.sendRequest(
        "GET",
        `http://127.0.0.1:${port}/deflate`,
        {},
        null,
      );
      expect(response.body).toBe('{"userId":1}');
    } finally {
      await new Promise<void>((resolve) => srv.close(() => resolve()));
    }
  });

  it("bhv transport 027 a decoded body drops the Content-Encoding and Content-Length headers", async () => {
    const body = zlib.gzipSync(Buffer.from('{"userId":1}', "utf-8"));
    const srv = http.createServer((_req, res) => {
      res.writeHead(200, {
        "Content-Type": "application/json",
        "Content-Encoding": "gzip",
        "Content-Length": String(body.length),
      });
      res.end(body);
    });
    await new Promise<void>((resolve) => srv.listen(0, "127.0.0.1", resolve));
    const client = new DefaultApiClient();
    try {
      const port = (srv.address() as { port: number }).port;
      const response = await client.sendRequest(
        "GET",
        `http://127.0.0.1:${port}/gzip`,
        {},
        null,
      );
      expect(response.body).toBe('{"userId":1}');
      expect(response.headers).not.toHaveProperty("content-encoding");
      expect(response.headers).not.toHaveProperty("content-length");
      expect(response.headers["content-type"]).toBe("application/json");
    } finally {
      await client.close();
      await new Promise<void>((resolve) => srv.close(() => resolve()));
    }
  });

  it("bhv transport 067 a successful response with no body is returned as a success with an empty body", async () => {
    const noBody = http.createServer((_req, res) => {
      res.writeHead(204);
      res.end();
    });
    await new Promise<void>((resolve) =>
      noBody.listen(0, "127.0.0.1", resolve),
    );
    const port = (noBody.address() as { port: number }).port;
    const client = new DefaultApiClient(
      TransportOptions.builder().maxRetries(0).build(),
    );
    try {
      const response = await client.sendRequest(
        "DELETE",
        `http://127.0.0.1:${port}/gone`,
        {},
        null,
      );
      expect(response.statusCode).toBe(204);
      expect(response.body).toBe("");
    } finally {
      await client.close();
      noBody.closeAllConnections();
      await new Promise<void>((resolve) => noBody.close(() => resolve()));
    }
  });

  it("bhv transport 037 passes an empty body declared gzip through as empty, not an error", async () => {
    // A zero-byte body still declared `Content-Encoding: gzip` has nothing to
    // inflate and no gzip magic: ensureDecoded must return it unchanged rather
    // than rejecting on the absent gzip stream.
    const out = await DefaultApiClient.ensureDecoded(Buffer.alloc(0), "gzip");
    expect(out.length).toBe(0);
  });

  it("bhv transport 033 passes a body declared Content-Encoding: identity through unchanged", async () => {
    global.fetch = (async (): Promise<Response> => {
      return new Response('{"userId":1}', {
        status: 200,
        headers: {
          "Content-Type": "application/json",
          "Content-Encoding": "identity",
        },
      });
    }) as typeof fetch;

    const client = new DefaultApiClient();
    const response = await client.sendRequest(
      "GET",
      "http://api.example/identity",
      {},
      null,
    );
    expect(response.statusCode).toBe(200);
    expect(response.body).toBe('{"userId":1}');
    const direct = await DefaultApiClient.ensureDecoded(
      Buffer.from('{"userId":1}', "utf-8"),
      "identity",
    );
    expect(direct.toString("utf-8")).toBe('{"userId":1}');
  });
});

