describe("DefaultApiClient transport misc behaviours", () => {
  const realFetch = global.fetch;
  const pick = (headers: Record<string, string>, name: string): string[] =>
    Object.entries(headers)
      .filter(([key]) => key.toLowerCase() === name)
      .map(([, value]) => value);
  const okJson = (): Response =>
    new Response('{"ok":true}', {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });
  afterEach(() => {
    global.fetch = realFetch;
  });

  it("bhv misc 262 cancelling a pending request surfaces the abort to the caller without wrapping it", async () => {
    global.fetch = (async (
      _input: unknown,
      init?: RequestInit,
    ): Promise<Response> =>
      new Promise<Response>((_resolve, reject) => {
        const signal = init?.signal;
        signal?.addEventListener("abort", () => reject(signal!.reason));
      })) as typeof fetch;
    const client = new DefaultApiClient(
      TransportOptions.builder().maxRetries(0).build(),
    );
    const controller = new AbortController();
    const pending = client.sendRequest(
      "GET",
      "https://example.invalid/slow",
      {},
      null,
      { signal: controller.signal },
    );
    controller.abort();
    const error = (await pending.catch((e: unknown) => e)) as Error;
    expect(error.name).toBe("AbortError");
    expect(error).not.toBeInstanceOf(NetworkError);
  });

  it("bhv misc 263 a per-call timeout longer than the client timeout lets a slow response complete", async () => {
    global.fetch = (async (): Promise<Response> => {
      await new Promise((resolve) => setTimeout(resolve, 150));
      return okJson();
    }) as typeof fetch;
    const client = new DefaultApiClient(
      TransportOptions.builder().timeout(50).maxRetries(0).build(),
    );
    const response = await client.sendRequest(
      "GET",
      "https://example.invalid/slow",
      {},
      null,
      { timeout: 2000 },
    );
    expect(response.statusCode).toBe(200);
  });

  it("bhv misc 265 a redirect to a non-HTTP scheme surfaces as an API error carrying the redirect status, not a network error", async () => {
    global.fetch = (async (): Promise<Response> =>
      new Response(null, {
        status: 302,
        headers: { Location: "ftp://files.example/x" },
      })) as typeof fetch;
    const client = new DefaultApiClient(
      TransportOptions.builder().followRedirects(true).build(),
    );
    const error = await client
      .sendRequest("GET", "https://api.example/start", {}, null)
      .catch((e: unknown) => e);
    expect(error).toBeInstanceOf(ApiError);
    expect(error).not.toBeInstanceOf(NetworkError);
    expect((error as ApiError).statusCode).toBe(302);
  });

  it("bhv misc 266 default headers supplied by the caller replace the SDK user agent and request id regardless of header name case", async () => {
    const seen: Record<string, string>[] = [];
    global.fetch = (async (
      _input: unknown,
      init?: RequestInit,
    ): Promise<Response> => {
      seen.push({ ...((init?.headers ?? {}) as Record<string, string>) });
      return okJson();
    }) as typeof fetch;
    const client = new DefaultApiClient(
      TransportOptions.builder()
        .injectRequestId(true)
        .defaultHeaders({
          "user-agent": "caller-agent",
          "X-REQUEST-ID": "caller-id",
        })
        .build(),
    );
    await client.sendRequest("GET", "https://example.invalid/items", {}, null);
    expect(pick(seen[0]!, "user-agent")).toEqual(["caller-agent"]);
    expect(pick(seen[0]!, "x-request-id")).toEqual(["caller-id"]);
  });

  it("bhv misc 267 a default header set on the transport is sent on the wire with each request", async () => {
    const seen: Record<string, string>[] = [];
    const injected = (async (
      _input: unknown,
      init?: RequestInit,
    ): Promise<Response> => {
      seen.push({ ...((init?.headers ?? {}) as Record<string, string>) });
      return okJson();
    }) as typeof fetch;
    const client = new DefaultApiClient(
      TransportOptions.builder()
        .fetch(injected)
        .defaultHeaders({ "X-Client-Default": "client-value" })
        .build(),
    );
    await client.sendRequest("GET", "https://example.invalid/items", {}, null);
    expect(pick(seen[0]!, "x-client-default")).toEqual(["client-value"]);
  });

  it("bhv misc 271 with no proxy configured the client connects directly even when a proxy environment variable is set", async () => {
    const srv = http.createServer((_req, res) => {
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end('{"direct":true}');
    });
    await new Promise<void>((resolve) => srv.listen(0, "127.0.0.1", resolve));
    const saved = process.env["HTTP_PROXY"];
    process.env["HTTP_PROXY"] = "http://127.0.0.1:9";
    const client = new DefaultApiClient(
      TransportOptions.builder().maxRetries(0).build(),
    );
    try {
      const port = (srv.address() as { port: number }).port;
      const response = await client.sendRequest(
        "GET",
        `http://127.0.0.1:${port}/direct`,
        {},
        null,
      );
      expect(response.statusCode).toBe(200);
      expect(response.body).toContain("direct");
    } finally {
      if (saved === undefined) delete process.env["HTTP_PROXY"];
      else process.env["HTTP_PROXY"] = saved;
      await client.close();
      await new Promise<void>((resolve) => srv.close(() => resolve()));
    }
  });

  it("bhv misc 272 credentials embedded in the proxy URL are accepted by an authenticating proxy end to end", async () => {
    /* undici tunnels every http:// origin through CONNECT: the proxy checks the
     * credential on the tunnel and serves the origin request inside it. */
    const seen: Array<string | undefined> = [];
    const expected = "Basic " + Buffer.from("user:pass").toString("base64");
    const origin = http.createServer((_req, res) => {
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end('{"via":"proxy"}');
    });
    const proxy = http.createServer((_req, res) => {
      res.writeHead(400);
      res.end();
    });
    proxy.on("connect", (req, socket) => {
      seen.push(req.headers["proxy-authorization"]);
      if (req.headers["proxy-authorization"] !== expected) {
        socket.end(
          'HTTP/1.1 407 Proxy Authentication Required\r\nProxy-Authenticate: Basic realm="proxy"\r\n\r\n',
        );
        return;
      }
      socket.write("HTTP/1.1 200 Connection Established\r\n\r\n");
      origin.emit("connection", socket);
    });
    await new Promise<void>((resolve) => proxy.listen(0, "127.0.0.1", resolve));
    const port = (proxy.address() as { port: number }).port;
    const client = new DefaultApiClient(
      TransportOptions.builder()
        .proxy(`http://user:pass@127.0.0.1:${port}`)
        .maxRetries(0)
        .build(),
    );
    try {
      const response = await client.sendRequest(
        "GET",
        "http://target.example.invalid/x",
        {},
        null,
      );
      expect(response.statusCode).toBe(200);
      expect(response.body).toContain("proxy");
      expect(seen[0]).toBe(expected);
    } finally {
      await client.close();
      await new Promise<void>((resolve) => proxy.close(() => resolve()));
    }
  });

  it("bhv misc 273 the request-id header carries a UUID v4 when enabled and is omitted when disabled", async () => {
    const seen: Record<string, string>[] = [];
    global.fetch = (async (
      _input: unknown,
      init?: RequestInit,
    ): Promise<Response> => {
      seen.push({ ...((init?.headers ?? {}) as Record<string, string>) });
      return okJson();
    }) as typeof fetch;
    await new DefaultApiClient(
      TransportOptions.builder().injectRequestId(true).build(),
    ).sendRequest("GET", "https://example.invalid/a", {}, null);
    await new DefaultApiClient(
      TransportOptions.builder().injectRequestId(false).build(),
    ).sendRequest("GET", "https://example.invalid/b", {}, null);
    expect(pick(seen[0]!, "x-request-id")[0]).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/,
    );
    expect(pick(seen[1]!, "x-request-id")).toEqual([]);
  });

  it("bhv misc 274 a non-2xx response is returned to the caller with its status code intact", async () => {
    global.fetch = (async (): Promise<Response> =>
      new Response('{"missing":true}', {
        status: 404,
        headers: { "Content-Type": "application/json" },
      })) as typeof fetch;
    const response = await new DefaultApiClient(
      TransportOptions.builder().maxRetries(0).build(),
    ).sendRequest("GET", "https://example.invalid/none", {}, null);
    expect(response.statusCode).toBe(404);
  });

  it("bhv misc 275 the request is sent with the intended HTTP method and the response is returned to the caller", async () => {
    const methods: string[] = [];
    global.fetch = (async (
      _input: unknown,
      init?: RequestInit,
    ): Promise<Response> => {
      methods.push(String(init?.method));
      return okJson();
    }) as typeof fetch;
    const response = await new DefaultApiClient(
      TransportOptions.builder().maxRetries(0).build(),
    ).sendRequest("PATCH", "https://example.invalid/items/1", {}, "{}");
    expect(methods).toEqual(["PATCH"]);
    expect(response.statusCode).toBe(200);
    expect(response.body).toContain("ok");
  });
});

describe("DefaultApiClient CA certificate misc behaviours", () => {
  it("bhv misc 270 a missing CA certificate file is rejected even when certificate verification is disabled, naming the certificate", () => {
    const missing = path.join(os.tmpdir(), "no-such-ca-misc-270.pem");
    expect(
      () =>
        new DefaultApiClient(
          TransportOptions.builder()
            .verifySsl(false)
            .caCertPath(missing)
            .build(),
        ),
    ).toThrow(missing);
  });
});

/* Captured at load, before any suite below replaces the global fetch. */
const nativeFetch = globalThis.fetch;

/** What a scripted raw server does with one connection: the hit number and the request head. */
type RawScript = (
  server: RawServer,
  socket: net.Socket,
  hit: number,
  head: string,
) => void | Promise<void>;

/**
 * An in-process HTTP/1.1 server on a raw socket, so a test can stall a body, cut it short or
 * reset the connection, which neither the shared mock server nor a plain HTTP server can do.
 */
class RawServer {
  hits = 0;
  readonly heads: string[] = [];
  /** True once the test released the scripts that wait on it. */
  released = false;
  /** Settles when the test, or closing the server, lets a script that waits on it carry on. */
  readonly release: Promise<void>;
  /** Settles when a connection was closed, by either side. */
  readonly gone: Promise<void>;
  private open!: () => void;
  private markGone!: () => void;
  private readonly sockets = new Set<net.Socket>();

  private constructor(private readonly listener: net.Server) {
    this.release = new Promise<void>((resolve) => {
      this.open = resolve;
    });
    this.gone = new Promise<void>((resolve) => {
      this.markGone = resolve;
    });
  }

  /** Starts a server that runs `script` for every connection it accepts. */
  static async serve(script: RawScript): Promise<RawServer> {
    const listener = net.createServer();
    const server = new RawServer(listener);
    listener.on("connection", (socket) => server.handle(socket, script));
    await new Promise<void>((resolve) =>
      listener.listen(0, "127.0.0.1", resolve),
    );
    return server;
  }

  url(pathAndQuery: string): string {
    return `http://127.0.0.1:${(this.listener.address() as net.AddressInfo).port}${pathAndQuery}`;
  }

  /** Lets every script that waits on `release` carry on. */
  letGo(): void {
    this.released = true;
    this.open();
  }

  private handle(socket: net.Socket, script: RawScript): void {
    this.sockets.add(socket);
    socket.on("error", () => undefined);
    socket.on("close", () => {
      this.sockets.delete(socket);
      this.markGone();
    });
    let head = "";
    const onData = (chunk: Buffer): void => {
      head += chunk.toString("latin1");
      if (!head.includes("\r\n\r\n")) {
        return;
      }
      socket.off("data", onData);
      const hit = ++this.hits;
      this.heads.push(head);
      Promise.resolve(script(this, socket, hit, head)).catch(() => undefined);
    };
    socket.on("data", onData);
  }

  async close(): Promise<void> {
    this.letGo();
    for (const socket of this.sockets) {
      socket.destroy();
    }
    await new Promise<void>((resolve) => this.listener.close(() => resolve()));
  }
}

function rawHead(
  socket: net.Socket,
  status: number,
  ...headers: string[]
): void {
  /* No Connection: close: undici reads a reset after the headers of such a response as its end. */
  const lines = [`HTTP/1.1 ${status} Test`, ...headers, "", ""];
  socket.write(lines.join("\r\n"), "latin1");
}

function rawChunk(socket: net.Socket, data: string): void {
  socket.write(`${Buffer.byteLength(data).toString(16)}\r\n${data}\r\n`);
}

function rawChunkBytes(socket: net.Socket, data: Buffer): void {
  socket.write(
    Buffer.concat([
      Buffer.from(`${data.length.toString(16)}\r\n`),
      data,
      Buffer.from("\r\n"),
    ]),
  );
}

function rawEnd(socket: net.Socket): void {
  socket.end("0\r\n\r\n");
}

/** Resets the connection instead of ending it cleanly. */
function rawReset(socket: net.Socket): void {
  socket.resetAndDestroy();
}

function pause(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Rejects when the promise does not settle within the time, so a hung test fails with a message. */
async function within<T>(
  promise: Promise<T>,
  ms: number,
  what: string,
): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      promise,
      new Promise<never>((_resolve, reject) => {
        timer = setTimeout(
          () => reject(new Error(`timed out waiting for ${what}`)),
          ms,
        );
      }),
    ]);
  } finally {
    clearTimeout(timer);
  }
}

/** Reads from the reader until at least `count` bytes arrived and returns them as text. */
async function readText(
  reader: ReadableStreamDefaultReader<Uint8Array>,
  count: number,
): Promise<string> {
  const chunks: Buffer[] = [];
  let total = 0;
  while (total < count) {
    const { done, value } = await reader.read();
    if (done) {
      break;
    }
    chunks.push(Buffer.from(value));
    total += value.byteLength;
  }
  return Buffer.concat(chunks).toString("utf8");
}

describe("DefaultApiClient streaming", () => {
  const servers: RawServer[] = [];
  const clients: DefaultApiClient[] = [];

  beforeEach(() => {
    globalThis.fetch = nativeFetch;
  });

  afterEach(async () => {
    for (const client of clients.splice(0)) {
      await client.close();
    }
    for (const server of servers.splice(0)) {
      await server.close();
    }
  });

  const serve = async (script: RawScript): Promise<RawServer> => {
    const server = await RawServer.serve(script);
    servers.push(server);
    return server;
  };

  const clientOf = (options?: TransportOptions): DefaultApiClient => {
    const client = new DefaultApiClient(
      options ?? TransportOptions.builder().build(),
    );
    clients.push(client);
    return client;
  };

  const streamOf = (server: RawServer, path: string) =>
    clientOf().sendStreaming("GET", server.url(path), {}, null);

  const asByteStream = (
    response: Awaited<ReturnType<typeof streamOf>>,
  ): ByteStream =>
    new ByteStream(response.statusCode, response.headers, response.body);

  const endlessChunks: RawScript = async (_server, socket) => {
    rawHead(socket, 200, "Transfer-Encoding: chunked");
    while (!socket.destroyed) {
      rawChunk(socket, "x".repeat(4096));
      await pause(5);
    }
  };

  it("bhv streaming 001 a binary stream call delivers the bytes in order and returns before the body has ended", async () => {
    const server = await serve(async (self, socket) => {
      rawHead(
        socket,
        200,
        "Content-Type: application/octet-stream",
        "Transfer-Encoding: chunked",
      );
      rawChunk(socket, "first-");
      await self.release;
      rawChunk(socket, "second");
      rawEnd(socket);
    });

    const response = await streamOf(server, "/items/blob");

    expect(response.statusCode).toBe(200);
    expect(server.released).toBe(false);
    const reader = response.body.getReader();
    expect(await readText(reader, 6)).toBe("first-");
    server.letGo();
    expect(await readText(reader, 6)).toBe("second");
    expect((await reader.read()).done).toBe(true);
  });

  it("bhv streaming 010 the call timeout bounds only the wait for the response headers, not the body", async () => {
    const server = await serve(async (_self, socket) => {
      rawHead(socket, 200, "Transfer-Encoding: chunked");
      rawChunk(socket, "ab");
      await pause(1200);
      rawChunk(socket, "cd");
      rawEnd(socket);
    });

    const response = await clientOf().sendStreaming(
      "GET",
      server.url("/items/blob"),
      {},
      null,
      {
        timeout: 400,
        maxRetries: 0,
      },
    );

    expect((await asByteStream(response).readAll()).toString("utf8")).toBe(
      "abcd",
    );
  });

  it("bhv streaming 011 the idle timeout raises a network timeout error when the server stalls in the middle of the body", async () => {
    const server = await serve(async (self, socket) => {
      rawHead(socket, 200, "Transfer-Encoding: chunked");
      rawChunk(socket, "ab");
      await self.release;
    });
    expect(TransportOptions.builder().build().idleTimeout).toBe(60000);
    expect(
      TransportOptions.builder().idleTimeout(0).build().idleTimeout,
    ).toBeNull();
    expect(
      TransportOptions.builder().idleTimeout(null).build().idleTimeout,
    ).toBeNull();
    expect(() => TransportOptions.builder().idleTimeout(-1)).toThrow(TypeError);

    const client = clientOf(
      TransportOptions.builder().idleTimeout(300).build(),
    );
    const response = await client.sendStreaming(
      "GET",
      server.url("/items/blob"),
      {},
      null,
    );
    const reader = response.body.getReader();
    expect(await readText(reader, 2)).toBe("ab");
    const started = Date.now();
    const failure = await reader.read().catch((error: unknown) => error);

    expect(failure).toBeInstanceOf(NetworkTimeoutError);
    expect((failure as NetworkTimeoutError).statusCode).toBe(0);
    expect(Date.now() - started).toBeLessThan(5000);
    expect(server.hits).toBe(1);
  });

  it("bhv streaming 012 a connection reset in the middle of the body raises a network error and is not retried", async () => {
    const server = await serve(async (_self, socket) => {
      rawHead(socket, 200, "Transfer-Encoding: chunked");
      rawChunk(socket, "ab");
      await pause(100);
      rawReset(socket);
    });

    const response = await streamOf(server, "/items/blob");

    await expect(asByteStream(response).readAll()).rejects.toBeInstanceOf(
      NetworkError,
    );
    expect(server.hits).toBe(1);
  });

  it("bhv streaming 013 a body shorter than its Content-Length raises a network error and is never a silent short success", async () => {
    const server = await serve((_self, socket) => {
      rawHead(socket, 200, "Content-Length: 10");
      socket.end("abcd");
    });

    const response = await streamOf(server, "/items/blob");

    await expect(asByteStream(response).readAll()).rejects.toBeInstanceOf(
      NetworkError,
    );
  });

  it("bhv streaming 014 a streaming call retries a 503 before the headers and then streams the retried response", async () => {
    const server = await serve((_self, socket, hit) => {
      if (hit === 1) {
        rawHead(socket, 503, "Retry-After: 0", "Content-Length: 4");
        socket.end("nope");
        return;
      }
      rawHead(socket, 200, "Content-Length: 5");
      socket.end("hello");
    });

    const response = await streamOf(server, "/items/blob");

    expect(response.statusCode).toBe(200);
    expect((await asByteStream(response).readAll()).toString("utf8")).toBe(
      "hello",
    );
    expect(server.hits).toBe(2);
  });

  it("bhv streaming 015 a streaming call never retries after the first body byte was delivered", async () => {
    const server = await serve(async (_self, socket) => {
      rawHead(socket, 200, "Transfer-Encoding: chunked");
      rawChunk(socket, "part");
      await pause(100);
      rawReset(socket);
    });

    const response = await streamOf(server, "/items/blob");
    const stream = asByteStream(response);
    const reader = stream.getReader();
    expect(await readText(reader, 4)).toBe("part");
    await expect(reader.read()).rejects.toBeInstanceOf(NetworkError);
    await pause(300);

    expect(server.hits).toBe(1);
  });

  it("bhv streaming 016 a streaming call follows a redirect before the body and strips credentials across origins", async () => {
    const target = await serve((_self, socket) => {
      rawHead(socket, 200, "Content-Length: 6");
      socket.end("landed");
    });
    const origin = await serve((_self, socket) => {
      rawHead(
        socket,
        302,
        `Location: ${target.url("/items/final")}`,
        "Content-Length: 0",
      );
      socket.end();
    });

    const response = await clientOf().sendStreaming(
      "GET",
      origin.url("/items/blob"),
      {
        Authorization: "Bearer secret-token",
        Cookie: "session=abc",
        "X-Trace": "kept",
      },
      null,
    );

    expect((await asByteStream(response).readAll()).toString("utf8")).toBe(
      "landed",
    );
    const sentToOrigin = origin.heads[0]!.toLowerCase();
    const sentToTarget = target.heads[0]!.toLowerCase();
    expect(sentToOrigin).toContain("authorization: bearer secret-token");
    expect(sentToTarget).not.toContain("authorization");
    expect(sentToTarget).not.toContain("cookie");
    expect(sentToTarget).toContain("x-trace: kept");
  });

  it("bhv streaming 019 closing a stream twice is safe and aborts the connection", async () => {
    const server = await serve(endlessChunks);

    const response = await streamOf(server, "/items/blob");
    const stream = asByteStream(response);
    const reader = stream.getReader();
    expect((await readText(reader, 4)).length).toBeGreaterThanOrEqual(4);
    reader.releaseLock();
    await stream.close();
    await stream.close();
    await response.close();

    await within(
      server.gone,
      10000,
      "the server to see the connection dropped",
    );
    await expect(stream.getReader().read()).rejects.toThrow("closed");
  });

  it("bhv streaming 020 cancelling the call aborts the stream and is never raised as a timeout", async () => {
    const silent = await serve(async (self) => {
      await self.release;
    });
    const stalled = await serve(async (self, socket) => {
      rawHead(socket, 200, "Transfer-Encoding: chunked");
      rawChunk(socket, "ab");
      await self.release;
    });
    const client = clientOf();

    const beforeHeaders = new AbortController();
    const waiting = client
      .sendStreaming("GET", silent.url("/items/blob"), {}, null, {
        signal: beforeHeaders.signal,
        maxRetries: 0,
      })
      .catch((error: unknown) => error);
    while (silent.hits === 0) {
      await pause(10);
    }
    beforeHeaders.abort();
    const early = await within(waiting, 10000, "the call to stop");
    expect((early as Error).name).toBe("AbortError");
    expect(early).not.toBeInstanceOf(NetworkTimeoutError);

    const inBody = new AbortController();
    const response = await client.sendStreaming(
      "GET",
      stalled.url("/items/blob"),
      {},
      null,
      { signal: inBody.signal },
    );
    const reader = response.body.getReader();
    expect(await readText(reader, 2)).toBe("ab");
    const pending = reader.read().catch((error: unknown) => error);
    await pause(300);
    inBody.abort();
    const late = await within(pending, 10000, "the read to stop");
    expect((late as Error).name).toBe("AbortError");
    expect(late).not.toBeInstanceOf(NetworkTimeoutError);
  });

  it("bhv streaming 022 the string form of a stream hides credentials, the query and the data", async () => {
    const server = await serve((_self, socket) => {
      rawHead(
        socket,
        200,
        "Content-Length: 7",
        "Set-Cookie: sid=secret-cookie",
      );
      socket.end("payload");
    });

    const response = await clientOf().sendStreaming(
      "GET",
      server.url("/items/blob?token=secret-query"),
      { Authorization: "Bearer secret-token" },
      null,
    );
    const stream = asByteStream(response);
    const reader = stream.getReader();
    expect(await readText(reader, 7)).toBe("payload");

    for (const shown of [
      String(stream),
      String(response),
      util.inspect(stream),
      util.inspect(response),
      JSON.stringify(stream),
      JSON.stringify(response),
    ]) {
      expect(shown).not.toContain("secret");
      expect(shown).not.toContain("payload");
      expect(shown).not.toContain("token");
      expect(shown).not.toContain("items");
    }
    expect(String(stream)).toBe("ByteStream{statusCode=200, bytesDelivered=7}");
  });

  it("bhv streaming 029 the read-all helper of a byte stream returns every byte in order and leaves the stream closed", async () => {
    const payload = Buffer.alloc(100_000);
    for (let i = 0; i < payload.length; i++) {
      payload[i] = (i * 31) & 0xff;
    }
    const server = await serve((_self, socket) => {
      rawHead(socket, 200, `Content-Length: ${payload.length}`);
      socket.end(payload);
    });

    const stream = asByteStream(await streamOf(server, "/items/blob"));

    expect((await stream.readAll()).equals(payload)).toBe(true);
    expect(String(stream)).toBe(
      "ByteStream{statusCode=200, bytesDelivered=100000}",
    );
    expect((await stream.readAll()).length).toBe(0);
    await expect(stream.close()).resolves.toBeUndefined();
  });

  it("bhv streaming 031 closing a live endless stream returns promptly and does not wait for the server to finish", async () => {
    const server = await serve(async (self, socket) => {
      rawHead(socket, 200, "Transfer-Encoding: chunked");
      rawChunk(socket, "tick");
      await self.release;
    });

    const response = await streamOf(server, "/items/events");
    const reader = response.body.getReader();
    expect(await readText(reader, 4)).toBe("tick");
    reader.releaseLock();
    const started = Date.now();
    await response.close();

    expect(Date.now() - started).toBeLessThan(2000);
  });

  it("bhv streaming 032 a reset or truncation after the headers raises a StreamError, and a StreamError is a network error", async () => {
    const reset = await serve(async (_self, socket) => {
      rawHead(socket, 200, "Transfer-Encoding: chunked");
      rawChunk(socket, "ab");
      await pause(100);
      rawReset(socket);
    });
    const cut = await serve((_self, socket) => {
      rawHead(socket, 200, "Content-Length: 10");
      socket.end("abcd");
    });

    for (const server of [reset, cut]) {
      const stream = asByteStream(await streamOf(server, "/items/blob"));
      const failure = await stream.readAll().catch((error: unknown) => error);

      expect(failure).toBeInstanceOf(StreamError);
      expect(failure).toBeInstanceOf(NetworkError);
      expect((failure as StreamError).statusCode).toBe(0);
    }
  });

  it("bhv streaming 033 stopping a stream early without reading it to the end releases the connection", async () => {
    const server = await serve(endlessChunks);

    const stream = asByteStream(await streamOf(server, "/items/events"));
    for await (const chunk of stream) {
      expect(chunk.byteLength).toBeGreaterThan(0);
      break;
    }

    await within(server.gone, 10000, "leaving the loop to drop the connection");
  });

  /** What an operation does for an event stream: one request per connection, over the transport. */
  const eventOpener = (server: RawServer, options: TransportOptions) => {
    const client = clientOf(options);
    return async (lastEventId: string): Promise<ByteStream> => {
      const headers: Record<string, string> = {};
      if (lastEventId !== "") {
        headers["Last-Event-ID"] = lastEventId;
      }
      const response = await client.sendStreaming(
        "GET",
        server.url("/items/events"),
        headers,
        null,
        { maxRetries: 0 },
      );
      return new ByteStream(
        response.statusCode,
        response.headers,
        response.body,
      );
    };
  };

  const eventsHead = (socket: net.Socket): void =>
    rawHead(
      socket,
      200,
      "Content-Type: text/event-stream",
      "Transfer-Encoding: chunked",
    );

  it("bhv streaming 006 a gzip encoded stream is decoded incrementally so the first item arrives before the body ends", async () => {
    const gzip = zlib.createGzip();
    const parts: Buffer[] = [];
    gzip.on("data", (chunk: Buffer) => parts.push(chunk));
    gzip.write("first\n");
    await new Promise<void>((resolve) => gzip.flush(() => resolve()));
    const head = Buffer.concat(parts.splice(0));
    await new Promise<void>((resolve) => {
      gzip.on("end", () => resolve());
      gzip.end("second\n");
      gzip.resume();
    });
    const rest = Buffer.concat(parts);
    const server = await serve(async (self, socket) => {
      rawHead(
        socket,
        200,
        "Content-Encoding: gzip",
        "Transfer-Encoding: chunked",
      );
      rawChunkBytes(socket, head);
      await self.release;
      rawChunkBytes(socket, rest);
      rawEnd(socket);
    });

    const response = await streamOf(server, "/items/export");
    const items = new JsonLinesStream<string>(
      asByteStream(response),
      (line) => line,
      1024,
      "GET",
      "/items/export",
    );

    expect((await within(items.next(), 5000, "the first item")).value).toBe(
      "first",
    );
    expect(server.released).toBe(false);
    server.letGo();
    expect((await items.next()).value).toBe("second");
    expect((await items.next()).done).toBe(true);
  });

  it("bhv streaming 007 a corrupt compressed stream raises an API error with the status and the decoder error and is not retried", async () => {
    const server = await serve((_self, socket) => {
      rawHead(socket, 200, "Content-Encoding: gzip", "Content-Length: 8");
      socket.end("notgzip!");
    });

    const response = await streamOf(server, "/items/export");
    const items = new JsonLinesStream<string>(
      asByteStream(response),
      (line) => line,
      1024,
      "GET",
      "/items/export",
    );
    const failure = await items.next().catch((error: unknown) => error);

    expect(failure).toBeInstanceOf(ApiError);
    expect(failure).not.toBeInstanceOf(NetworkError);
    expect((failure as ApiError).statusCode).toBe(200);
    expect((failure as ApiError).cause).toBeDefined();
    expect(server.hits).toBe(1);
  });

  it("bhv sse 007 an SSE stream reconnects after the connection drops and sends the last event id in Last-Event-ID", async () => {
    const server = await serve((_self, socket, hit) => {
      if (hit >= 3) {
        rawHead(socket, 204);
        return;
      }
      eventsHead(socket);
      rawChunk(
        socket,
        hit === 1
          ? "id: 1\ndata: a\n\nid: 2\ndata: b\n\n"
          : "id: 3\ndata: c\n\n",
      );
      rawEnd(socket);
    });

    const stream = await SseStream.open<string>(
      eventOpener(server, TransportOptions.builder().build()),
      null,
      null,
      { reconnectDelay: 1 },
      false,
      false,
      "GET",
      "/items/events",
    );
    const data: string[] = [];
    for await (const event of stream) {
      data.push(event.data);
    }

    expect(data).toEqual(["a", "b", "c"]);
    expect(server.heads[0]!.toLowerCase()).not.toContain("last-event-id");
    expect(server.heads[1]!.toLowerCase()).toContain("last-event-id: 2");
    expect(server.heads[2]!.toLowerCase()).toContain("last-event-id: 3");
  });

  it("bhv sse 015 an idle timeout on an SSE stream counts as a lost connection and reconnects", async () => {
    const server = await serve(async (self, socket, hit) => {
      eventsHead(socket);
      if (hit === 1) {
        rawChunk(socket, "id: 1\ndata: a\n\n");
        await self.release;
        return;
      }
      rawChunk(socket, "id: 2\ndata: b\n\n");
      rawEnd(socket);
    });

    const stream = await SseStream.open<string>(
      eventOpener(server, TransportOptions.builder().idleTimeout(300).build()),
      null,
      null,
      { reconnectDelay: 1, maxReconnects: 1 },
      false,
      false,
      "GET",
      "/items/events",
    );

    expect((await stream.next()).value!.data).toBe("a");
    expect((await stream.next()).value!.data).toBe("b");
    expect(server.heads[1]!.toLowerCase()).toContain("last-event-id: 1");
  });

  it("bhv sse 018 an SSE comment line such as a heartbeat is skipped and counts as activity for the idle timeout", async () => {
    const server = await serve(async (_self, socket) => {
      eventsHead(socket);
      for (let beat = 0; beat < 8; beat++) {
        rawChunk(socket, ": heartbeat\n\n");
        await pause(100);
      }
      rawChunk(socket, "data: late\n\n");
      rawEnd(socket);
    });

    const stream = await SseStream.open<string>(
      eventOpener(server, TransportOptions.builder().idleTimeout(400).build()),
      null,
      null,
      { reconnectDelay: 1, maxReconnects: 0 },
      false,
      false,
      "GET",
      "/items/events",
    );

    expect((await stream.next()).value!.data).toBe("late");
    expect(server.hits).toBe(1);
  });
});

/** What a scripted raw server received as the body of one request. */
interface Upload {
  readonly bytes: Buffer;
  readonly chunked: boolean;
}

/**
 * Reads the body that follows `head` on the socket: a chunked one chunk by chunk and one with a
 * Content-Length to its end. `onFirst` runs as soon as bytes of the body have arrived, while the
 * rest is still to come.
 */
function readUpload(
  socket: net.Socket,
  head: string,
  onFirst: () => void = () => undefined,
): Promise<Upload> {
  const lower = head.toLowerCase();
  const chunked = lower.includes("transfer-encoding: chunked");
  const declared = /content-length: (\d+)/.exec(lower);
  const wanted = declared === null ? 0 : Number(declared[1]);
  let pending = Buffer.from(head.slice(head.indexOf("\r\n\r\n") + 4), "latin1");
  const received: Buffer[] = [];
  return new Promise<Upload>((resolve) => {
    let seen = 0;
    const settle = (): void => {
      socket.off("data", onData);
      socket.off("close", settle);
      resolve({ bytes: Buffer.concat(received), chunked });
    };
    const consume = (): boolean => {
      if (!chunked) {
        received.push(pending);
        seen += pending.length;
        pending = Buffer.alloc(0);
        return seen >= wanted;
      }
      for (;;) {
        const lineEnd = pending.indexOf("\r\n");
        if (lineEnd < 0) {
          return false;
        }
        const size = parseInt(
          pending.subarray(0, lineEnd).toString("latin1"),
          16,
        );
        if (size === 0) {
          return true;
        }
        if (pending.length < lineEnd + 2 + size + 2) {
          return false;
        }
        received.push(pending.subarray(lineEnd + 2, lineEnd + 2 + size));
        pending = pending.subarray(lineEnd + 2 + size + 2);
      }
    };
    const onData = (chunk: Buffer): void => {
      pending = Buffer.concat([pending, chunk]);
      const complete = consume();
      onFirst();
      if (complete) {
        settle();
      }
    };
    socket.on("data", onData);
    socket.on("close", settle);
    if (pending.length > 0 || wanted === 0) {
      const complete = consume();
      if (pending.length > 0 || received.length > 0) {
        onFirst();
      }
      if (complete) {
        settle();
      }
    }
  });
}

function rawReply(
  socket: net.Socket,
  status: number,
  ...headers: string[]
): void {
  rawHead(socket, status, ...headers, "Content-Length: 0");
  socket.end();
}

function patterned(size: number): Buffer {
  const data = Buffer.alloc(size);
  for (let index = 0; index < size; index++) {
    data[index] = (index * 31 + 7) & 0xff;
  }
  return data;
}

/** An async iterable that counts how often it is asked to stop early, which is what a close is. */
function countingChunks(
  data: Buffer,
): AsyncIterable<Uint8Array> & { returns: number } {
  const counter = {
    returns: 0,
    [Symbol.asyncIterator](): AsyncIterator<Uint8Array> {
      let done = false;
      return {
        async next(): Promise<IteratorResult<Uint8Array>> {
          if (done) {
            return { done: true, value: undefined };
          }
          done = true;
          return { done: false, value: data };
        },
        async return(): Promise<IteratorResult<Uint8Array>> {
          counter.returns++;
          return { done: true, value: undefined };
        },
      };
    },
  };
  return counter;
}

/** A Readable that is not destroyed when it ends, so only a close by the SDK would destroy it. */
function callerReadable(data: Buffer): Readable {
  return Readable.from([data], { autoDestroy: false });
}

describe("DefaultApiClient uploads", () => {
  const servers: RawServer[] = [];
  const files: string[] = [];
  const clients: DefaultApiClient[] = [];

  beforeEach(() => {
    globalThis.fetch = nativeFetch;
  });

  afterEach(async () => {
    for (const client of clients.splice(0)) {
      await client.close();
    }
    for (const server of servers.splice(0)) {
      await server.close();
    }
    for (const file of files.splice(0)) {
      fs.rmSync(file, { force: true });
    }
  });

  const serve = async (script: RawScript): Promise<RawServer> => {
    const server = await RawServer.serve(script);
    servers.push(server);
    return server;
  };

  const put = (
    server: RawServer,
    body: BodySource,
    options?: { maxRetries?: number },
  ) => {
    const client = new DefaultApiClient(TransportOptions.builder().build());
    clients.push(client);
    return client.sendRequest(
      "PUT",
      server.url("/items/blob"),
      { "Content-Type": "application/octet-stream" },
      body,
      options,
    );
  };

  it("bhv streaming 023 a streamed upload of unknown length is sent chunked and arrives intact", async () => {
    const data = patterned(300_000);
    let firstSeen!: () => void;
    const gate = new Promise<void>((resolve) => {
      firstSeen = resolve;
    });
    const seen: Array<Promise<Upload>> = [];
    const server = await serve(async (_self, socket, _hit, head) => {
      const upload = readUpload(socket, head, firstSeen);
      seen.push(upload);
      await upload;
      rawReply(socket, 200);
    });
    /* The second half is not readable until the server has the first, so a client that buffered
     * the stream before sending would wait here for good. */
    async function* gated(): AsyncGenerator<Uint8Array> {
      const half = data.length / 2;
      for (let position = 0; position < half; position += 4096) {
        yield data.subarray(position, Math.min(position + 4096, half));
      }
      await within(
        gate,
        15_000,
        "the first half of the upload to reach the server",
      );
      for (let position = half; position < data.length; position += 4096) {
        yield data.subarray(position, Math.min(position + 4096, data.length));
      }
    }

    const response = await put(server, BodySource.once(gated()));

    expect(response.statusCode).toBe(200);
    const head = server.heads[0]!.toLowerCase();
    expect(head).toContain("transfer-encoding: chunked");
    expect(head).not.toContain("content-length");
    const upload = await seen[0]!;
    expect(upload.chunked).toBe(true);
    expect(upload.bytes.equals(data)).toBe(true);
  });

  it("bhv streaming 024 a streamed upload with a known length sends Content-Length", async () => {
    const data = patterned(100_000);
    const file = path.join(
      os.tmpdir(),
      `upload-${process.pid}-${Date.now()}.bin`,
    );
    fs.writeFileSync(file, data);
    files.push(file);
    const seen: Array<Promise<Upload>> = [];
    const server = await serve(async (_self, socket, _hit, head) => {
      const upload = readUpload(socket, head);
      seen.push(upload);
      await upload;
      rawReply(socket, 200);
    });
    const sources = [
      BodySource.of(data),
      BodySource.ofFile(file),
      BodySource.fromFactory(() => Readable.from([data]), data.length),
      BodySource.once(Readable.from([data]), data.length),
    ];

    for (const source of sources) {
      expect((await put(server, source)).statusCode).toBe(200);
    }

    expect(seen).toHaveLength(sources.length);
    for (let index = 0; index < sources.length; index++) {
      const head = server.heads[index]!.toLowerCase();
      expect(head).toContain(`content-length: ${data.length}`);
      expect(head).not.toContain("transfer-encoding");
      const upload = await seen[index]!;
      expect(upload.chunked).toBe(false);
      expect(upload.bytes.equals(data)).toBe(true);
    }
    expect(sources[0]!.toString()).toBe("BodySource[bytes, 100000 bytes]");
    expect(sources[1]!.toString()).toBe("BodySource[file, 100000 bytes]");
    expect(sources[3]!.toString()).toBe("BodySource[single use, 100000 bytes]");
    expect(BodySource.fromFactory(() => Readable.from([data])).toString()).toBe(
      "BodySource[factory, length unknown]",
    );
  });

  it("bhv streaming 025 a caller supplied upload stream is never closed by the SDK", async () => {
    const server = await serve(async (_self, socket, hit, head) => {
      await readUpload(socket, head);
      rawReply(socket, hit === 2 ? 503 : 200, "Retry-After: 0");
    });

    const readable = callerReadable(patterned(5000));
    expect((await put(server, BodySource.once(readable))).statusCode).toBe(200);
    expect(readable.destroyed).toBe(false);

    const refused = callerReadable(patterned(5000));
    expect(
      (await put(server, BodySource.once(refused), { maxRetries: 0 }))
        .statusCode,
    ).toBe(503);
    expect(refused.destroyed).toBe(false);

    const iterable = countingChunks(patterned(5000));
    expect((await put(server, BodySource.once(iterable))).statusCode).toBe(200);
    expect(iterable.returns).toBe(0);

    const web = new ReadableStream<Uint8Array>({
      start(controller) {
        controller.enqueue(patterned(5000));
        controller.close();
      },
    });
    expect((await put(server, BodySource.once(web))).statusCode).toBe(200);
    expect(web.locked).toBe(false);

    const made = countingChunks(patterned(5000));
    expect(
      (
        await put(
          server,
          BodySource.fromFactory(() => made),
        )
      ).statusCode,
    ).toBe(200);
    expect(made.returns).toBeGreaterThanOrEqual(1);
  });

  it("bhv streaming 026 a replayable upload is rewound and retried after a 503 and a single use upload is not retried and surfaces the original error", async () => {
    const data = patterned(20_000);
    const seen: Array<Promise<Upload>> = [];
    const server = await serve(async (_self, socket, hit, head) => {
      const upload = readUpload(socket, head);
      seen.push(upload);
      await upload;
      rawReply(socket, hit === 1 ? 503 : 200, "Retry-After: 0");
    });
    let opens = 0;

    const response = await put(
      server,
      BodySource.fromFactory(() => {
        opens++;
        return Readable.from([data]);
      }),
    );

    expect(response.statusCode).toBe(200);
    expect(server.hits).toBe(2);
    expect(opens).toBe(2);
    expect((await seen[0]!).bytes.equals(data)).toBe(true);
    expect((await seen[1]!).bytes.equals(data)).toBe(true);

    const failing = await serve(async (_self, socket, _hit, head) => {
      await readUpload(socket, head);
      rawReply(socket, 503, "Retry-After: 0");
    });
    const original = await put(failing, BodySource.once(Readable.from([data])));
    expect(original.statusCode).toBe(503);
    expect(failing.hits).toBe(1);

    const resetting = await serve(async (_self, socket, _hit, head) => {
      await readUpload(socket, head);
      rawReset(socket);
    });
    await expect(
      put(resetting, BodySource.once(Readable.from([data]))),
    ).rejects.toBeInstanceOf(NetworkError);
    expect(resetting.hits).toBe(1);
  });

  it("bhv streaming 027 a 307 or 308 with a single use upload is refused and the body is never buffered", async () => {
    const data = patterned(20_000);
    for (const status of [307, 308]) {
      const landed: Array<Promise<Upload>> = [];
      const target = await serve(async (_self, socket, _hit, head) => {
        const upload = readUpload(socket, head);
        landed.push(upload);
        await upload;
        rawReply(socket, 200);
      });
      const origin = await serve(async (_self, socket, _hit, head) => {
        await readUpload(socket, head);
        rawReply(socket, status, `Location: ${target.url("/items/final")}`);
      });
      const once = callerReadable(data);

      const refused = await put(origin, BodySource.once(once)).then(
        () => null,
        (error: unknown) => error,
      );

      expect(refused).toBeInstanceOf(ApiError);
      expect((refused as ApiError).message).toContain(
        "Refusing to replay a streamed request body",
      );
      expect((refused as ApiError).statusCode).toBe(status);
      expect(target.hits).toBe(0);
      expect(origin.hits).toBe(1);
      expect(once.destroyed).toBe(false);

      const followed = await put(
        origin,
        BodySource.fromFactory(() => Readable.from([data])),
      );
      expect(followed.statusCode).toBe(200);
      expect(landed).toHaveLength(1);
      expect((await landed[0]!).bytes.equals(data)).toBe(true);
    }
  });
});
